#!/usr/bin/env python3
# -*- coding: utf-8 -*-
# Task 469: обновление системного промта kip8test (post-Task 469
# ПЕРЕНОС — зеркальная фиксация переноса в kip8).
import io
import sys

PATH = 'Системный_промт_для_приложения_КИПиА.md'
with io.open(PATH, encoding='utf-8') as f:
    src = f.read()

CUR_MARK = '> **Версия документа:** 2026-10-03 (post-Task 468 ПЕРЕНОС'
PREV_MARK = '> **Версия документа (предыдущая):**'

NEW_LINE3 = '> **Версия документа:** 2026-10-03 (post-Task 469 ПЕРЕНОС: Task 469 перенесён из kip8test@d56a2ea3 в боевой kip8 ОДНИМ инкрементом SW kipia-v504→v505 — КЛИЕНТ-ONLY, серверных шагов НЕТ (Apps Script не менялся); заявка: «Перепиши описание раздела на "Периодические работы на участке КИП ИОС, выполняемые в начале и в конце каждого месяца. Функционал: Отметка выполнения — …, Хранение отметок — …, Правка отметки — …, Обновление — …"»): СУТЬ (окно «Описание раздела» Task 468, только ТЕКСТ — раскладка/стили не менялись): (1) вводный абзац переписан: «Периодические работы на участке КИП ИОС, выполняемые в начале и в конце каждого месяца.» (прежде — «Плановые мероприятия — периодические работы предприятия…» с упоминанием образца «Пример таблицы мероприятий.xlsx» и группировки строк); (2) пункт «Хранение отметок» сокращён до «отметки записываются в архив.» (прежде раскрывал файл «Мероприятия_КИП_ИОС» (лист «Архив»)); (3) пункт «Мобильная версия» УДАЛЕН — 5 → 4 пункта функционала (отметка выполнения/хранение отметок/правка отметки/обновление — формулировки заявки ДОСЛОВНО, порядок по заявке); «Мероприятия_КИП_ИОС» остаётся идентификатором файла в JS (из текста описания убран). ПЕРЕНОС: scripts/task469-transfer.py в kip8 (де-изоляция ×15, «дифф диффов»: репо-дифф 59 == эталону kip8test@235f4f0e↔kip8@7564816, дифф задач 15 идентичен; .gs не тронуты — синхронны, Code.gs kip8-версия жива); тесты kip8 5310/0 = паритет 5304 + 6 task344 (маппинг v693→v505 (519)/v694→v506 (123)/негатив партии v692→v504 (1: test-task469)/негатив 468 v691→v503 (1)/негатив 467 v690→v502 (1)/негативы 466 v689→v501 (2)/исторические; test-task344 v504→v505; run-all +469); SMOKE task469-smoke-k8.py 19/19 (порт 8997, ключи без префикса: раскладка Task 468 жива — карточка слева обнимает таблицу, окно до правого края; точные тексты заявки, старые фрагменты отсутствуют, 4 пункта; 1100px колонка; 375px Task 464 жив; 0 JS). ПОДВОДНЫЕ КАМНИ: (а) перенос-скрипт ОДНОРАЗОВЫЙ; (б) НОВЫЙ: test-task469.js ассертит IMAGE_CACHE_VERSION — в kip8 кэш картинок БЕЗ суффикса -test- (kipia-images-v3, не kipia-images-test-v3) — в перенос-скрипт добавлен маппинг (kipia-images-test-v3 → kipia-images-v3), без него тест kip8 падал 5309/1; (в) test-task468.js адаптирован под 469 (5→4 пункта, сняты ассерты «Мобильная версия»/«Пример таблицы мероприятий» — ассерты убраны, не перевраны). БАМП: task469-bump-tests.py (guards v693→v694 (123)/ассерты v692→v693 (516), 153 файла) — test-task469.js писался ПОСЛЕ бампа с финальной v693. Тесты kip8test 5304/0 (177 файлов; НОВЫЙ test-task469.js ×25: лид ×3 (точный текст заявки/старые формулировки удалены/pe-desc-lead в разметке), функционал ×7 (4 пункта дословно/«Хранение» сокращён/«Мобильная версия» удалён/порядок пунктov/«Функционал» жив), каркас ×5 (aside+aria/структура порядок блоков/одно окно/маркер 469/таблица не тронута), изоляция ×6 (раскладка 468 жива/@media 1199/мобайл 464/JS/файл жив вне описания/CSS-правила окна), SW ×4 (v693/v692 нет/комментарий 469/IMAGE_CACHE_VERSION не тронут)). Браузер task469-browser-check.py 34/34 (порт 8999: A 1600 — раскладка жива: карточка влево ±2/окно справа до края/обнимает таблицу/nowrap/без скролла; B содержание — точный лид/4 пункта дословно/старые фрагменты ×5 отсутствуют; C 1100 — колонка, лид виден; D 375 — Task 464 жив + лид виден; E светлая тема; 0 JS). VLM ×3 (десктоп: точный лид, 4 пункта, без дефектов; мобайл: лид и первый пункт видны, остальное ниже скролла — норма; светлая: читаемо). Артефакты download/kip8test-task469/ (×4 png) + download/kip8-task469/ (smoke ×1 png). DEPLOY-Task469-plan-events-description-rewrite.md (КЛИЕНТ-ONLY — серверных шагов НЕТ; скопирован в kip8). ТЕКУЩЕЕ СОСТОЯНИЕ: kip8test @d56a2ea3 SW `kipia-test-v693` (guard v694), тесты 5304/0; kip8 @352753f SW `kipia-v505` (guard v506), тесты 5310/0 (паритет + 6 task344) — Task 469 выкачан в ОБОИХ репо, открытых хвостов нет; десктопы — CI-автосинк. СЛЕДУЮЩИЙ НОМЕР ЗАДАЧИ: 470 (в обоих репо).'

if CUR_MARK not in src:
    print('ОШИБКА: не найдена строка версии post-468-ПЕРЕНОС')
    sys.exit(1)

n_prev_before = src.count(PREV_MARK)

i3 = src.index(CUR_MARK)
i3end = src.index('\n', i3)
old_line3 = src[i3:i3end]

# (а) удалить самую старую строку «предыдущая» (храним 2 последних)
if src.count(PREV_MARK) > 2:
    iprev = src.rindex(PREV_MARK)
    iprev_end = src.index('\n', iprev)
    src = src[:iprev] + src[iprev_end + 1:]

# (б) строка 3 → новая версия + «предыдущая» из старой строки 3
new_prev = PREV_MARK + ' ' + old_line3[len('> **Версия документа:** '):]
src = src[:i3] + NEW_LINE3 + '\n' + new_prev + src[i3end:]

# (в) «Текущая версия кэша» v692 → v693
old_cache = '> **Текущая версия кэша:** `kipia-test-v692`'
new_cache = '> **Текущая версия кэша:** `kipia-test-v693`'
if old_cache not in src:
    print('ОШИБКА: не найдена строка текущей версии кэша')
    sys.exit(1)
src = src.replace(old_cache, new_cache, 1)

# (г) строка «Инкрементируй» — следующие версии
old_inc = 'Формат: `kipia-test-v692` → `kipia-test-v693` (для kip8test) или `kipia-v503` → `kipia-v504` (для kip8)'
new_inc = 'Формат: `kipia-test-v693` → `kipia-test-v694` (для kip8test) или `kipia-v504` → `kipia-v505` (для kip8)'
if old_inc not in src:
    print('ОШИБКА: не найдена строка «Инкрементируй»')
    sys.exit(1)
src = src.replace(old_inc, new_inc, 1)

# (д) ожидание тестов 5279/5285 → 5304/5310
old_exp = '# Ожидается: 5279 passed, 0 failed (kip8test; в kip8 — 5285 passed, 0 failed)'
new_exp = '# Ожидается: 5304 passed, 0 failed (kip8test; в kip8 — 5310 passed, 0 failed)'
if old_exp not in src:
    print('ОШИБКА: не найдена строка ожидания тестов')
    sys.exit(1)
src = src.replace(old_exp, new_exp, 1)

# (е) контроль
assert src.count(NEW_LINE3) == 1
assert src.count(PREV_MARK) <= n_prev_before + 1

with io.open(PATH, 'w', encoding='utf-8') as f:
    f.write(src)
print('OK: промт kip8test обновлён до post-Task 469 ПЕРЕНОС')
print('  предыдущих строк: %d (было %d)' % (src.count(PREV_MARK), n_prev_before))
